const started = new Date().toISOString();
return [{
  json: {
    probe_started_at: started,
    deepseek_model: 'deepseek-v4-flash',
    qwen_model: 'qwen/qwen3.5-flash-02-23@reasoning_effort=none',
    prompt_system: 'Reply with exactly the word OK. No other text.',
    prompt_user: 'healthcheck',
  },
}];

const prep = $('HC — Prepare').first().json || {};
const item = $input.first().json || {};
const raw = item.output ?? item.text ?? item.response ?? item.content ?? null;
const errMsg = item.error?.message || item.error || (typeof item.message === 'string' ? item.message : null);
const rawText = raw == null ? null : String(raw).trim();
const looksOk = !!rawText && !/forbidden|not supported|401|403|country|region|territory/i.test(rawText + ' ' + String(errMsg || ''));
const deepseekOk = looksOk && !errMsg;
const error = deepseekOk
  ? null
  : String(errMsg || item.description || (rawText ? 'deepseek_agent_empty' : 'deepseek_agent_failed')).slice(0, 500);

return [{
  json: {
    ...prep,
    deepseek_ok: deepseekOk,
    deepseek_error: error,
    deepseek_raw: rawText ? rawText.slice(0, 200) : null,
  },
}];

const j = $input.first().json || {};
return [{
  json: {
    ok: true,
    llm_provider: 'deepseek',
    model: j.deepseek_model || 'deepseek-v4-flash',
    error: null,
    deepseek_ok: true,
    qwen_ok: null,
    probed_at: new Date().toISOString(),
    probe_started_at: j.probe_started_at || null,
  },
}];

const prep = $('HC — DeepSeek Result').first().json || {};
const item = $input.first().json || {};
const raw = item.output ?? item.text ?? item.response ?? item.content ?? null;
const errMsg = item.error?.message || item.error || (typeof item.message === 'string' ? item.message : null);
const rawText = raw == null ? null : String(raw).trim();
const qwenOk = !!rawText && !errMsg;
const qwenError = qwenOk
  ? null
  : String(errMsg || (rawText ? 'qwen_agent_empty' : 'qwen_agent_failed')).slice(0, 500);

const ok = qwenOk;
return [{
  json: {
    ok,
    llm_provider: ok ? 'qwen' : 'none',
    model: ok ? (prep.qwen_model || 'qwen/qwen3.5-flash-02-23@reasoning_effort=none') : null,
    error: ok
      ? null
      : `deepseek=${prep.deepseek_error || 'fail'}; qwen=${qwenError}`,
    deepseek_ok: !!prep.deepseek_ok,
    deepseek_error: prep.deepseek_error || null,
    qwen_ok: qwenOk,
    qwen_error: qwenError,
    qwen_raw: rawText ? rawText.slice(0, 200) : null,
    probed_at: new Date().toISOString(),
    probe_started_at: prep.probe_started_at || null,
  },
}];
